using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public class ConfigResource
{
    private static readonly JsonSerializerOptions s_jsonOptions = new() { WriteIndented = true };

    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "Application Settings",
        MimeType = "application/json")]
    [Description("Returns the current application configuration.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Features = new { EnableCaching = true, MaxConnections = 100 },
            SupportedRegions = new[] { "us-east-1", "eu-west-1" }
        };

        return JsonSerializer.Serialize(config, s_jsonOptions);
    }

    [McpServerResource(
        UriTemplate = "config://app/feature/{featureName}",
        Name = "Feature Flag",
        MimeType = "application/json")]
    [Description("Returns the status of a specific feature flag.")]
    public static string GetFeatureFlag(string featureName)
    {
        var flags = new Dictionary<string, bool>
        {
            ["caching"] = true,
            ["dark-mode"] = false,
            ["beta-api"] = true
        };

        var enabled = flags.TryGetValue(featureName, out var value) && value;

        return JsonSerializer.Serialize(
            new { Feature = featureName, Enabled = enabled },
            s_jsonOptions);
    }
}

